const D = { energy: .55, scale: 1, speed: 1, density: .45, veil: .3, hue: 44, x: .5, y: .5, style: 'paint', seed: 0, alpha: 65 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- The scene is a coated surface, and the coating is failing.
// Adhesion goes first at the edges, so a chip lifts IN PLACE from its own spot — it does not
// rain in from the top of frame. Each chip: hairline crack -> lifts and curls, throwing a soft
// shadow that is what sells it as coming off a surface -> lets go and drifts a short way ->
// gone, leaving the scene behind it clean. Chips run staggered lives, so the surface is always
// mid-failure and never resolves.
// Polite by construction: nothing is drawn where the coating is still stuck down, so at rest
// this layer is nearly invisible and the scene reads through it.
const u = Math.min(width, height);
const sd = P.seed | 0;
function hsh(ix, iy, iz) {
  let h = (Math.imul(ix | 0, 374761393) + Math.imul(iy | 0, 668265263) + Math.imul(iz | 0, 1274126177) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}
const tt = K.t, style = P.style;
const dr1 = Math.sin(tt * 0.061), dr2 = Math.sin(tt * 0.143 + 1.7), dr3 = Math.sin(tt * 0.229 + 0.4);
const ctx = drawingContext;
const aa = Math.max(0, Math.min(100, P.alpha)) / 100;
const hb = ((P.hue % 360) + 360) % 360, hh = hb / 360;

// raking light: azimuth on two incommensurate rates, so every lit edge and every shadow in the
// frame swings continuously — the motion floor, and the thing that makes chips read as 3D
const az = tt * 0.047 + Math.sin(tt * 0.019) * 0.95 + 1.2;
const lxa = Math.cos(az), lya = Math.sin(az);

// ---- palettes: coating, its lit edge, and what is under it ----
let COAT, LIT, UNDER;
if (style === 'gilt') { COAT = [206, 168, 70]; LIT = [255, 240, 186]; UNDER = [92, 34, 28]; }
else if (style === 'emulsion') { COAT = [206, 208, 204]; LIT = [252, 253, 255]; UNDER = [128, 132, 140]; }
else if (style === 'ash') { COAT = [124, 112, 106]; LIT = [236, 122, 48]; UNDER = [26, 22, 22]; }
else if (style === 'outline') { COAT = [120, 190, 210]; LIT = [190, 235, 245]; UNDER = [60, 110, 130]; }
else {
  const cr = 0.55 + 0.42 * Math.cos(6.2831 * hh), cg = 0.54 + 0.34 * Math.cos(6.2831 * (hh + 0.06)), cb = 0.50 + 0.26 * Math.cos(6.2831 * (hh + 0.14));
  COAT = [cr * 255, cg * 255, cb * 255]; LIT = [Math.min(255, cr * 320 + 40), Math.min(255, cg * 320 + 40), Math.min(255, cb * 300 + 40)]; UNDER = [70, 62, 54];
}

// ---- the chip lattice ----
const nx = Math.max(3, Math.round((4 + P.density * 11) / Math.max(0.5, P.scale * 0.7 + 0.3)));
const ny = Math.max(2, Math.round(nx * height / width));
const cwid = width / nx, chgt = height / ny;
const PER = (17 + (1 - P.density) * 14) / Math.max(0.2, P.speed);   // a chip's whole life, seconds

const shadows = [];
const buckets = []; for (let b = 0; b < 6; b++) buckets.push([]);
const edges = [];
const hairs = [];

for (let j = 0; j < ny; j++) {
  for (let i = 0; i < nx; i++) {
    const n = j * nx + i;
    const ph0 = hsh(i, j, 3);
    const ptot = tt / PER + ph0;
    const cyc = Math.floor(ptot);                  // each life gets a fresh shape and spot
    const ph = ptot - cyc;
    const gx = (i + 0.5) * cwid + (hsh(n, cyc, 5) - 0.5) * cwid * 0.7 + (P.x - 0.5) * width * 0.12;
    const gy = (j + 0.5) * chgt + (hsh(n, cyc, 7) - 0.5) * chgt * 0.7 + (P.y - 0.5) * height * 0.12;
    const r = u * (0.028 + 0.040 * hsh(n, cyc, 9)) * Math.max(0.3, P.scale);
    const spin = hsh(n, cyc, 11) * 6.2831;

    // ---- lifecycle ----
    let curl = 0, lift = 0, dx = 0, dy = 0, rot = spin, op = 1;
    if (ph < 0.38) {
      // still stuck down: nothing but a hairline crack round its edge, fading up
      const g = ph / 0.38;
      hairs.push([gx, gy, r, n, cyc, spin, Math.min(1, g * 1.6)]);
      continue;
    } else if (ph < 0.66) {
      // lifting and curling — the shadow underneath is what says "this is coming off"
      const g = (ph - 0.38) / 0.28;
      curl = g * 0.62; lift = g;
      dx = lxa * -r * 0.10 * g; dy = lya * -r * 0.10 * g;
      op = Math.min(1, g * 2.2);
    } else if (ph < 0.94) {
      // let go: drifts a SHORT way from its own spot and fades. It is shed, not rained down.
      const g = (ph - 0.66) / 0.28;
      curl = 0.62 + g * 0.24;
      lift = 1;
      const dr = hsh(n, cyc, 13) * 6.2831;
      dx = Math.cos(dr) * u * 0.10 * g + Math.sin(tt * 0.7 + spin) * u * 0.012 * g;
      dy = Math.sin(dr) * u * 0.055 * g + u * 0.13 * g * g;      // it does fall, but only a little
      rot = spin + g * (hsh(n, cyc, 15) - 0.5) * 3.4;
      op = 1 - g * g;
    } else { continue; }
    if (op < 0.02) continue;

    // chip polygon: irregular, foreshortened as it rolls up, then rotated
    const NV = 6;
    const pts = [];
    const cs = Math.cos(rot), sn = Math.sin(rot);
    const fore = 1 - curl * 0.72;
    for (let k = 0; k < NV; k++) {
      const a = (k / NV) * 6.2831 + (hsh(n, cyc * 7 + k, 17) - 0.5) * 0.55;
      const rr = r * (0.58 + 0.52 * hsh(n, cyc * 7 + k, 19));
      const px = Math.cos(a) * rr, py = Math.sin(a) * rr * fore;
      pts.push(gx + dx + px * cs - py * sn, gy + dy + px * sn + py * cs);
    }
    // how the raking light strikes this chip's face once it has tipped up
    const face = Math.max(0, Math.cos(rot - az)) * curl;
    const shade = 0.42 + 0.58 * face * (0.4 + P.energy);
    const b = Math.min(5, Math.floor(shade * 6));
    buckets[b].push([pts, op]);
    // the cast shadow, offset away from the lamp and growing as the chip rises
    if (style !== 'outline') {
      const so = r * 0.30 * lift;
      shadows.push([pts, -lxa * so, -lya * so, op * lift]);
    }
    // the curled leading edge catches the lamp hard — the brightest line in the frame
    edges.push([pts, op * (0.35 + curl * 0.9)]);
  }
}

// ---- draw: batched, so a whole failing surface costs about nine draw calls ----
ctx.save();
ctx.lineJoin = 'round'; ctx.lineCap = 'round';

// hairline cracks in the still-adhered coating (+ the faint tint of the coating itself)
if (P.veil > 0.01) {
  ctx.beginPath();
  for (const h of hairs) {
    const [gx, gy, r, n, cyc, spin, g] = h;
    const cs = Math.cos(spin), sn = Math.sin(spin);
    for (let k = 0; k <= 6; k++) {
      const a = ((k % 6) / 6) * 6.2831 + (hsh(n, cyc * 7 + (k % 6), 17) - 0.5) * 0.55;
      const rr = r * (0.58 + 0.52 * hsh(n, cyc * 7 + (k % 6), 19));
      const px = Math.cos(a) * rr, py = Math.sin(a) * rr;
      const X = gx + px * cs - py * sn, Y = gy + px * sn + py * cs;
      if (k === 0) ctx.moveTo(X, Y); else ctx.lineTo(X, Y);
    }
  }
  ctx.fillStyle = 'rgba(' + (COAT[0] | 0) + ',' + (COAT[1] | 0) + ',' + (COAT[2] | 0) + ',' + (aa * P.veil * 0.14).toFixed(3) + ')';
  ctx.fill();
  ctx.strokeStyle = 'rgba(' + (UNDER[0] | 0) + ',' + (UNDER[1] | 0) + ',' + (UNDER[2] | 0) + ',' + (aa * P.veil * 0.5).toFixed(3) + ')';
  ctx.lineWidth = Math.max(0.5, u * 0.0010); ctx.stroke();
}

// shadows first
if (shadows.length) {
  for (let pass = 0; pass < 3; pass++) {            // 3 offset passes = a cheap soft shadow
    ctx.beginPath();
    const k = 1 + pass * 0.5;
    for (const s of shadows) {
      const [pts, ox, oy, o] = s;
      ctx.moveTo(pts[0] + ox * k, pts[1] + oy * k);
      for (let q = 2; q < pts.length; q += 2) ctx.lineTo(pts[q] + ox * k, pts[q + 1] + oy * k);
    }
    ctx.fillStyle = 'rgba(6,5,8,' + (aa * 0.14 * (0.5 + P.energy * 0.5)).toFixed(3) + ')';
    ctx.fill();
  }
}

// chip faces, one fill per light bucket
for (let b = 0; b < 6; b++) {
  if (!buckets[b].length) continue;
  ctx.beginPath();
  let mo = 0;
  for (const c of buckets[b]) {
    const [pts, o] = c;
    ctx.moveTo(pts[0], pts[1]);
    for (let q = 2; q < pts.length; q += 2) ctx.lineTo(pts[q], pts[q + 1]);
    if (o > mo) mo = o;
  }
  const sh = (b + 0.5) / 6;
  if (style === 'outline') {
    ctx.strokeStyle = 'rgba(' + (COAT[0] | 0) + ',' + (COAT[1] | 0) + ',' + (COAT[2] | 0) + ',' + (aa * mo * 0.8).toFixed(3) + ')';
    ctx.lineWidth = Math.max(0.6, u * 0.0016); ctx.stroke();
  } else {
    const r = COAT[0] * sh, g2 = COAT[1] * sh, b2 = COAT[2] * sh;
    ctx.fillStyle = 'rgba(' + (r | 0) + ',' + (g2 | 0) + ',' + (b2 | 0) + ',' + (aa * mo * 0.92).toFixed(3) + ')';
    ctx.fill();
  }
}

// the lit curled edge
if (style !== 'outline' && edges.length) {
  ctx.beginPath();
  let mo = 0;
  for (const e of edges) {
    const [pts, o] = e;
    ctx.moveTo(pts[0], pts[1]);
    for (let q = 2; q < pts.length; q += 2) ctx.lineTo(pts[q], pts[q + 1]);
    ctx.closePath();
    if (o > mo) mo = o;
  }
  ctx.strokeStyle = 'rgba(' + (LIT[0] | 0) + ',' + (LIT[1] | 0) + ',' + (LIT[2] | 0) + ',' + (aa * mo * 0.5 * (0.4 + P.energy * 0.9)).toFixed(3) + ')';
  ctx.lineWidth = Math.max(0.5, u * 0.0016 * (0.5 + P.energy));
  ctx.stroke();
}
ctx.restore();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
